class Stack:
    def __init__(self):
        self.items = []

    def push(self, v):
        self.items.append(v)

    def pop(self):
        return self.items.pop() if self.items else None

    def peek(self):
        return self.items[-1] if self.items else None

s = Stack()
for v in (1, 2, 3):
    s.push(v)
print(s.pop(), s.peek())
print("剩余:", s.items)

PAIRS = {")": "(", "]": "[", "}": "{"}

def is_balanced(text):
    stack = []
    for ch in text:
        if ch in "([{":
            stack.append(ch)
        elif ch in PAIRS:
            if not stack or stack.pop() != PAIRS[ch]:
                return False
    return not stack

print(is_balanced("a(b[c]d)e"))
print(is_balanced("f(x))"))

OPS = {"+": lambda a, b: a + b, "-": lambda a, b: a - b,
       "*": lambda a, b: a * b, "/": lambda a, b: int(a / b)}

def eval_rpn(tokens):
    stack = []
    for t in tokens:
        if t in OPS:
            b = stack.pop()
            a = stack.pop()
            stack.append(OPS[t](a, b))
        else:
            stack.append(int(t))
    return stack[0]

print(eval_rpn(["2", "1", "+", "3", "*"]))

class MinStack:
    def __init__(self):
        self.stack = []
        self.mins = []

    def push(self, v):
        self.stack.append(v)
        current = self.mins[-1] if self.mins else v
        self.mins.append(min(v, current))

    def pop(self):
        self.stack.pop()
        self.mins.pop()

    def min(self):
        return self.mins[-1]

s = MinStack()
for v in (5, 2, 7, 1):
    s.push(v)
print("栈顶:", s.stack[-1], "| 最小:", s.min())
s.pop()
print("弹出一个后最小:", s.min())

class QueueByStacks:
    def __init__(self):
        self.inbox = []
        self.outbox = []

    def enqueue(self, v):
        self.inbox.append(v)

    def dequeue(self):
        if not self.outbox:
            while self.inbox:
                self.outbox.append(self.inbox.pop())
        return self.outbox.pop() if self.outbox else None

q = QueueByStacks()
q.enqueue(1)
q.enqueue(2)
print(q.dequeue())
q.enqueue(3)
print(q.dequeue(), q.dequeue())

def next_greater(nums):
    result = [-1] * len(nums)
    stack = []
    for i, v in enumerate(nums):
        while stack and nums[stack[-1]] < v:
            index = stack.pop()
            result[index] = v
        stack.append(i)
    return result

print(next_greater([2, 1, 3, 4, 1]))

from collections import deque

def max_window(nums, k):
    dq = deque()
    out = []
    for i, v in enumerate(nums):
        while dq and nums[dq[-1]] <= v:
            dq.pop()
        dq.append(i)
        if dq[0] <= i - k:
            dq.popleft()
        if i >= k - 1:
            out.append(nums[dq[0]])
    return out

print(max_window([1, 3, -1, -3, 5, 3, 6, 7], 3))

from collections import deque

def process(tasks):
    dq = deque()
    log = []
    for action, value in tasks:
        if action == "push_back":
            dq.append(value)
        elif action == "push_front":
            dq.appendleft(value)
        elif action == "pop_back":
            log.append(dq.pop())
        elif action == "pop_front":
            log.append(dq.popleft())
    return dq, log

dq, log = process([("push_back", 1), ("push_front", 2),
                   ("push_back", 3), ("pop_front", None)])
print("弹出:", log, "| 剩余:", list(dq))
